def bisection(func, a, b, ftol=1e-10):
    fa = func(a)
    converged = False

    while not converged:
        midpoint = 0.5 * (a + b)
        f_mid = func(midpoint)

        if fa * f_mid < 0:
            b = midpoint
        else:
            a = midpoint
            fa = f_mid

        # Check for convergence
        if abs(f_mid) < ftol:
            converged = True

    return midpoint

def newton_raphson(func, dfunc, x0, ftol=1e-10):
    x = x0
    converged = False

    while not converged:
        fx = func(x)
        x = x - fx / dfunc(x)

        # Check for convergence
        if abs(fx) < ftol:
            converged = True

    return x
